from __future__ import annotations

MAX_DIM = 100
MIN_QUALITY = 30
GOOD_QUALITY = 60
SATURATION_LIMIT = 5

# (field, error message, max allowed size); max None means unlimited.
_GRID_FIELDS = (
    ("width", "bad width", MAX_DIM),
    ("height", "bad height", MAX_DIM),
    ("cell_size", "bad cell size", None),
)


def accumulate_grid(raw: object) -> dict:
    if not isinstance(raw, dict):
        return {"ok": False, "error": "malformed input"}
    if "grid" not in raw or "observations" not in raw or "fill_value" not in raw:
        return {"ok": False, "error": "missing field"}

    grid = raw["grid"]
    if not isinstance(grid, dict):
        return {"ok": False, "error": "bad grid"}
    if not all(f in grid for f in ("width", "height", "cell_size")):
        return {"ok": False, "error": "bad grid"}
    for field, error, limit in _GRID_FIELDS:
        value = grid[field]
        if not isinstance(value, int) or value < 1 or (limit is not None and value > limit):
            return {"ok": False, "error": error}
    width, height, cell_size = grid["width"], grid["height"], grid["cell_size"]

    if not isinstance(raw["fill_value"], int):
        return {"ok": False, "error": "bad fill value"}
    observations = raw["observations"]
    if not isinstance(observations, list):
        return {"ok": False, "error": "bad observations"}

    sums = {}
    counts = {}
    degraded = {}
    dropped = 0
    rejected = 0
    saturated = 0
    tolerance = cell_size // 2
    for obs in observations:
        if not isinstance(obs, dict):
            return {"ok": False, "error": "bad observation"}
        for field in ("x", "y", "value", "quality"):
            if field not in obs or not isinstance(obs[field], int):
                return {"ok": False, "error": "bad observation"}
        if not 0 <= obs["quality"] <= 100:
            return {"ok": False, "error": "bad observation"}

        if obs["quality"] < MIN_QUALITY:
            rejected = rejected + 1
            continue

        col = _axis_index(obs["x"], width, cell_size, tolerance)
        if col is None:
            dropped = dropped + 1
            continue
        row = _axis_index(obs["y"], height, cell_size, tolerance)
        if row is None:
            dropped = dropped + 1
            continue

        key = (row, col)
        if counts.get(key, 0) >= SATURATION_LIMIT:
            saturated = saturated + 1
            continue
        sums[key] = sums.get(key, 0) + obs["value"]
        counts[key] = counts.get(key, 0) + 1
        if obs["quality"] < GOOD_QUALITY:
            degraded[key] = True

    cells, flags = _build_grid(sums, counts, degraded, width, height, raw["fill_value"])
    coverage = len(counts) * 100 // (width * height)
    return {
        "ok": True,
        "cells": cells,
        "flags": flags,
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
        "coverage": coverage,
        "line": _summary_line(width * height, len(counts), dropped, rejected, saturated, coverage),
    }


def _axis_index(value: int, size: int, cell_size: int, tolerance: int) -> int | None:
    if value < 0:
        return None
    index = value // cell_size
    if index < size:
        return index
    if value - size * cell_size < tolerance:
        return size - 1
    return None


def _build_grid(sums: dict, counts: dict, degraded: dict, width: int, height: int, fill_value: int):
    cells = []
    flags = []
